TITLE = 'Gate Positions on Cube Faces'


def main():
    print(TITLE + ' - working demo')
    side = 12000
    for face in ['East', 'North', 'South', 'West']:
        for i, frac in enumerate([0.25, 0.5, 0.75], start=1):
            print('%s gate %d at %.2f along the face = %s stadia' % (face, i, frac, format(frac * side, ',.0f')))


main()
